memoryBank.splice(0,memoryBank.length,...pdfMemory);function escHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function similarityScore(a,b){const clean=s=>s.replace(/\s|[.,!?·()「」『』“”"':;]/g,'');const grams=s=>{const z=[];for(let i=0;i<Math.max(1,s.length-1);i++)z.push(s.slice(i,i+2));return z};const aa=grams(clean(a)),bb=grams(clean(b)),set=new Set(bb),hit=aa.filter(x=>set.has(x)).length;return Math.min(100,Math.round(200*hit/(aa.length+bb.length)||0))}
function beginStudyNew(mode){studyMode=mode;studyQuestions=mode==='memory'?memoryBank:mode==='ox'?oxBank:pdfTranslationBank;studyOrder=Array.from({length:studyQuestions.length},(_,i)=>i).sort(()=>Math.random()-.5);studyIndex=0;studyAnswered=false;$('homeView').style.display='none';$('notebookView').style.display='none';$('historyView').style.display='none';$('practiceIntro').style.display='flex';$('practiceGrid').style.display='grid';const title=mode==='memory'?'암기 문제':mode==='ox'?'밑줄 문법 OX':'문법 문장 문제';$('practiceIntro').querySelector('h1').textContent=title;$('practiceIntro').querySelector('p').textContent=mode==='memory'?'PDF의 핵심 규칙과 표현을 떠올려 직접 입력해요.':mode==='ox'?'밑줄 친 부분이 문법적으로 맞는지 O/X로 판단하고, 틀리면 바른 형태를 확인해요.':'PDF 예제 문장을 직접 해석하고 문법 포인트와 해석 순서를 확인해요.';document.querySelector('.top-title').innerHTML='<button id="homeBack" type="button">‹ 홈</button>　›　<b>'+title+'</b>';document.getElementById('homeBack').onclick=goHome;document.querySelector('.sentence-label').textContent=mode==='memory'?'기억나는 구조와 표현을 직접 입력해 보세요.':mode==='ox'?'밑줄 친 부분의 문법이 맞는지 골라 보세요.':'다음 영어 문장을 한국어로 해석해 보세요.';document.querySelector('.answer-label').childNodes[0].textContent=mode==='grammar'?'내 해석 ':'내 답 ';$('answer').style.display=mode==='ox'?'none':'block';$('answer-label').style.display=mode==='ox'?'none':'flex';$('submit').style.display=mode==='ox'?'none':'inline-block';$('roundTotal').textContent=' / '+studyQuestions.length+(mode==='grammar'?'개 문장':mode==='ox'?'문항':'개 항목');renderStudyQuestionNew();window.scrollTo(0,0)}
function ensureOx(){let node=$('oxControls');if(node)return node;node=document.createElement('div');node.id='oxControls';node.className='ox-controls';node.innerHTML='<button type="button" data-answer="true">O　맞다</button><button type="button" data-answer="false">X　틀리다</button>';node.querySelectorAll('button').forEach(b=>b.onclick=()=>gradeOxNew(b.dataset.answer==='true'));$('english').after(node);return node}
function renderStudyQuestionNew(){studyAnswered=false;const q=studyQuestions[studyOrder[studyIndex]];$('topic').textContent=q.topic||'PDF 핵심 문법';$('number').textContent=studyMode==='ox'?'PDF 예제 '+String(q.no).padStart(3,'0'):(studyMode==='grammar'?'예문 ':'암기 ')+(studyIndex+1);$('roundCount').textContent=studyIndex+1;$('roundTotal').textContent=' / '+studyQuestions.length+(studyMode==='grammar'?'개 문장':studyMode==='ox'?'문항':'개 항목');$('answer').value='';$('answer').disabled=false;$('submit').disabled=false;$('result').classList.remove('show');$('charCount').textContent='0자';$('doneCount').textContent=studyIndex;$('progress').style.width=((studyIndex+1)/studyQuestions.length*100)+'%';$('progressText').textContent=(studyIndex+1)+' / '+studyQuestions.length+' 문제';$('focus1').textContent=(q.focus||['핵심 구조 확인'])[0];$('focus2').textContent=(q.focus||['','POINT 확인'])[1]||'';$('english').textContent=q.en;$('answer').style.display=studyMode==='ox'?'none':'block';$('answer-label').style.display=studyMode==='ox'?'none':'flex';$('submit').style.display=studyMode==='ox'?'none':'inline-block';let ox=ensureOx();ox.style.display=studyMode==='ox'?'flex':'none';ox.querySelectorAll('button').forEach(b=>b.disabled=false);if(studyMode==='ox')$('english').innerHTML=escHtml(q.en).replace(escHtml(q.target),'<u class="target-underline">'+escHtml(q.target)+'</u>')}
function showFeedback(q,score,hits){$('scoreRing').textContent=score+'점';$('scoreRing').className='score-ring'+(score<45?' low':score<72?' mid':'');$('resultTitle').textContent=score>=72?'좋아요, 핵심을 잘 잡았어요':score>=45?'기준 답과 비교해 보세요':'문법 규칙을 다시 확인해 봐요';$('resultSummary').textContent='문법 유형을 기준으로 즉시 채점했어요. 문장 구조와 외울 표현을 함께 확인하세요.';$('model').textContent=q.model||'';$('criteria').innerHTML=q.checks&&q.checks.length?q.checks.map((c,i)=>'<div class="criterion '+(hits[i]?'ok':'miss')+'"><span>'+escHtml(c.name)+'</span><span class="mark">'+(hits[i]?'✓ 반영됨':'! 확인 필요')+'</span></div>').join(''):'<div class="criterion '+(score===100?'ok':'miss')+'"><span>'+escHtml(q.topic||'문법 유형')+'</span><span class="mark">'+(score===100?'✓ 정답':'! 다시 확인')+'</span></div>';$('steps').innerHTML=(q.steps||[]).map((v,i)=>'<div class="step-row"><b>'+(i+1)+'</b><span>'+escHtml(v.replace(/^[①②③④⑤⑥⑦⑧⑨⑩]\s*/,''))+'</span></div>').join('');$('grammar').innerHTML='<b>'+escHtml(q.topic||'문법')+'</b>'+escHtml(q.grammar||'PDF의 개념 설명을 확인하세요.');$('memorize').innerHTML='<b>✦ 외워둘 내용</b>'+escHtml(q.memorize||'핵심 문형을 다시 읽고 예문과 함께 기억하세요.');$('answer').disabled=true;$('submit').disabled=true;$('result').classList.add('show');$('result').scrollIntoView({behavior:'smooth',block:'nearest'})}
function gradeStudyNew(){if(studyMode==='ox'){showToast('O 또는 X를 선택해 주세요.');return}const q=studyQuestions[studyOrder[studyIndex]],val=$('answer').value.trim();if(!val){showToast('먼저 답을 입력해 주세요.');$('answer').focus();return}if(studyAnswered)return;studyAnswered=true;let score,hits;if(studyMode==='grammar'){score=similarityScore(val,q.model);hits=q.checks.map(c=>c.terms.some(t=>val.replace(/\s/g,'').includes(t.replace(/\s/g,''))))}else{hits=q.checks.map(c=>c.terms.some(t=>val.toLowerCase().replace(/\s/g,'').includes(t.toLowerCase().replace(/\s/g,''))));score=Math.round(hits.filter(Boolean).length/hits.length*100)}saveStudyRecord(q,val,hits,score);showFeedback(q,score,hits);if(studyMode==='grammar')$('resultSummary').textContent='기준 해석과 입력한 답의 글자 묶음 유사도를 바탕으로 한 참고 점수예요. 다른 자연스러운 번역은 낮게 나올 수 있으니 모범 해석과 문법 해설도 함께 확인하세요.'}
function gradeOxNew(answer){if(studyAnswered)return;const q=studyQuestions[studyOrder[studyIndex]],hit=answer===q.correct;studyAnswered=true;const value=hit?100:0;saveStudyRecord(q,answer?'O':'X',[hit],value);ensureOx().querySelectorAll('button').forEach(b=>b.disabled=true);showFeedback(q,value,[hit]);$('resultTitle').textContent=hit?'정답이에요':'정답을 확인해 봐요';$('resultSummary').textContent='정답은 '+(q.correct?'O':'X')+'입니다.'+(q.fix?' 올바른 형태: '+q.fix:'')+' '+q.grammar;$('model').textContent=q.fix?'수정 문장: '+q.en.replace(q.target,q.fix):'문장: '+q.en}
window.revealAnswer=function(){ answer.scrollIntoView({behavior:'smooth',block:'center'}) };function nextStudyNew(){studyIndex++;if(studyIndex>=studyQuestions.length){showToast('한 바퀴 완료! 새 순서로 다시 시작합니다.');beginStudyNew(studyMode);return}renderStudyQuestionNew()}
function shuffleCurrentNew(){if(!studyQuestions||!studyQuestions.length)return;studyOrder=Array.from({length:studyQuestions.length},(_,i)=>i).sort(()=>Math.random()-.5);studyIndex=0;renderStudyQuestionNew();showToast('문제 순서를 새로 섞었어요.');window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.mode-card')[0].onclick=()=>beginStudyNew('memory');document.querySelectorAll('.mode-card')[1].onclick=()=>beginStudyNew('grammar');document.querySelectorAll('.mode-card')[2].onclick=()=>beginStudyNew('ox');$('submit').onclick=gradeStudyNew;document.querySelector('#result .primary').onclick=nextStudyNew;$('shuffleQuestions').onclick=shuffleCurrentNew;$('grammarTotal').textContent=pdfTranslationBank.length+'개 PDF 문장';$('oxTotal').textContent=oxBank.length+'문항';$('memoryTotal').textContent=memoryBank.length+'개 핵심 항목';



